package ru.folio.notes;

import android.graphics.*;
import android.view.*;
import android.view.animation.DecelerateInterpolator;
import android.widget.*;

/** First-run feature tour; replayable from the library. Does not touch any notebook. */
final class Onboarding extends FrameLayout {
    static final String SEEN="onboarding_studio_seen";
    static final String[] TITLES={"Линия чувствует\nвас.","Сначала\nпримерьте.","Всё нужное —\nу кончика пера.","Ошибаться\nможно.","Точная форма.\nСвободная мысль.","Продолжение —\nодним свайпом.","Соберите\nсвой пенал.","Идеи принадлежат\nвам."};
    static final String[] DESCRIPTIONS={"Нажмите чуть сильнее — линия станет шире. Ослабьте нажим — и кисть оставит лёгкий след.","Подведите ластик к экрану: вы заранее увидите, какая часть штриха исчезнет. Отведите перо — запись вернётся.","Два быстрых сжатия открывают палитру у наконечника. Одно сжатие меняет перо. Жесты можно переназначить.","Коротко коснитесь листа двумя пальцами, чтобы отменить последнее действие. И продолжайте писать.","Откройте «Чертёж», выберите циркуль, центр и радиус. Проведите пером только нужную часть окружности.","Свайп пером от края холста перелистывает страницы. В инструменте навигации листать можно в любом месте.","Оставьте под рукой любимые инструменты. Меняйте порядок и открывайте параметры повторным касанием выбранного инструмента.","Экспортируйте записи в PDF и PNG или сохраните редактируемую тетрадь Folio — вместе со всеми страницами."};
    final MainActivity a;int index;FeatureDemo demo;LinearLayout copy,stage;TextView title,description,counter,next,back;Dots dots;float downX,downY;boolean closing,launchSetup;
    Onboarding(MainActivity a,int page){super(a);this.a=a;index=Math.max(0,Math.min(7,page));setBackgroundColor(Studio.BG);setClickable(true);setFocusableInTouchMode(true);setContentDescription("Знакомство с Folio");build();}
    static void show(MainActivity a,boolean force){if(a.intro!=null)return;if(!force&&a.prefs.getBoolean(SEEN,false)){if(a.prefs.getBoolean(HandwritingSetup.PENDING,false))HandwritingSetup.show(a,true);return;}if(a.canvas!=null)a.canvas.finishGesture(false);a.intro=new Onboarding(a,0);a.root.addView(a.intro,new FrameLayout.LayoutParams(-1,-1));a.intro.requestFocus();a.systemBars(false);Studio.enter(a.intro,0);if(a.rotation!=null)a.rotation.update();}
    void build(){removeAllViews();LinearLayout layout=a.column();a.pad(layout,a.wide()?42:22,24);addView(layout,new FrameLayout.LayoutParams(-1,-1));LinearLayout head=a.row();TextView brand=a.text("folio",30,Studio.TEXT,true);brand.setLetterSpacing(-.06f);head.addView(brand);a.space(head,12);TextView badge=a.text("МЕСТО ДЛЯ МЫСЛЕЙ",9,Studio.MUTED,true);badge.setLetterSpacing(.15f);head.addView(badge);a.stretch(head);head.addView(Studio.button(a,"Позже",false,()->finish(true)));layout.addView(head,new LinearLayout.LayoutParams(-1,a.dp(52)));
        stage=new LinearLayout(a);stage.setOrientation(a.wide()?LinearLayout.HORIZONTAL:LinearLayout.VERTICAL);stage.setGravity(Gravity.CENTER_VERTICAL);LinearLayout.LayoutParams stageLp=new LinearLayout.LayoutParams(-1,0,1);stageLp.topMargin=a.dp(16);stageLp.bottomMargin=a.dp(12);layout.addView(stage,stageLp);
        copy=a.column();copy.setGravity(Gravity.CENTER_VERTICAL);a.pad(copy,a.wide()?10:0,12);counter=Studio.eyebrow(a,"");copy.addView(counter);title=a.text("",a.wide()?43:29,Studio.TEXT,true);title.setLetterSpacing(-.04f);title.setLineSpacing(a.dp(2),1);copy.addView(title);description=a.text("",a.wide()?16:14,Studio.MUTED,false);description.setLineSpacing(a.dp(7),1);LinearLayout.LayoutParams dl=new LinearLayout.LayoutParams(-1,-2);dl.topMargin=a.dp(20);copy.addView(description,dl);
        demo=new FeatureDemo(a,index);if(a.wide()){stage.addView(copy,new LinearLayout.LayoutParams(0,-1,.43f));a.space(stage,34);stage.addView(demo,new LinearLayout.LayoutParams(0,-1,.57f));}else {stage.addView(demo,new LinearLayout.LayoutParams(-1,0,1));stage.addView(copy,new LinearLayout.LayoutParams(-1,-2));}
        LinearLayout footer=a.row();dots=new Dots();footer.addView(dots,new LinearLayout.LayoutParams(0,a.dp(48),1));back=Studio.button(a,"Назад",false,()->go(index-1));footer.addView(back);a.space(footer,10);next=Studio.button(a,"Дальше",true,()->{if(index==7)finish(true);else go(index+1);});footer.addView(next);layout.addView(footer,new LinearLayout.LayoutParams(-1,a.dp(54)));fill();
    }
    void fill(){counter.setText(String.format(java.util.Locale.ROOT,"%02d  /  08     ·     %s",index+1,new String[]{"НАЖИМ","ЛАСТИК","ПАЛИТРА","ОТМЕНА","ЦИРКУЛЬ","СТРАНИЦЫ","ИНСТРУМЕНТЫ","ЭКСПОРТ"}[index]));title.setText(TITLES[index]);description.setText(DESCRIPTIONS[index]+(index==2?"\nДля жестов корпуса нужен подключённый мост пера.":""));next.setText(index==7?"Начать писать":"Дальше");back.setVisibility(index==0?INVISIBLE:VISIBLE);dots.invalidate();demo.scene(index);announceForAccessibility(title.getText());}
    void go(int target){if(target<0||target>7||closing)return;int direction=target>index?1:-1;index=target;if(!Studio.motion()){fill();return;}stage.animate().cancel();stage.animate().alpha(0).translationX(a.dp(-18*direction)).setDuration(130).withEndAction(()->{fill();stage.setTranslationX(a.dp(22*direction));stage.animate().alpha(1).translationX(0).setDuration(330).setInterpolator(new DecelerateInterpolator(1.8f)).start();}).start();}
    void finish(boolean remember){if(closing)return;closing=true;launchSetup=remember&&!a.prefs.getBoolean(HandwritingSetup.SEEN,false);if(remember){android.content.SharedPreferences.Editor e=a.prefs.edit().putBoolean(SEEN,true);if(launchSetup)e.putBoolean(HandwritingSetup.PENDING,true);e.apply();}if(!Studio.motion()){closeNow();return;}animate().alpha(0).translationY(a.dp(-16)).setDuration(220).withEndAction(this::closeNow).start();}
    void closeNow(){animate().cancel();stage.animate().cancel();if(getParent() instanceof android.view.ViewGroup)((android.view.ViewGroup)getParent()).removeView(this);if(a.intro==this)a.intro=null;if(a.rotation!=null)a.rotation.update();if(launchSetup&&!a.isFinishing()&&!a.isDestroyed()){launchSetup=false;HandwritingSetup.show(a,true);}}
    public boolean onInterceptTouchEvent(MotionEvent event){if(event.getActionMasked()==0){downX=event.getX();downY=event.getY();}return event.getActionMasked()==2&&Math.abs(event.getX()-downX)>a.dp(28)&&Math.abs(event.getX()-downX)>Math.abs(event.getY()-downY)*1.4f;}
    public boolean onTouchEvent(MotionEvent e){if(e.getActionMasked()==1&&Math.abs(e.getX()-downX)>a.dp(65))go(index+(e.getX()<downX?1:-1));return true;}
    final class Dots extends View {final Paint p=new Paint(3);Dots(){super(a);setContentDescription("Слайды знакомства");}protected void onDraw(Canvas c){float x=0;for(int i=0;i<8;i++){float w=a.dp(i==index?25:6);p.setColor(i==index?Studio.ACCENT:Studio.LINE);c.drawRoundRect(new RectF(x,getHeight()/2f-a.dp(3),x+w,getHeight()/2f+a.dp(3)),a.dp(3),a.dp(3),p);x+=w+a.dp(8);}}public boolean onTouchEvent(MotionEvent e){if(e.getActionMasked()==1){float x=0;for(int i=0;i<8;i++){float w=a.dp(i==index?25:6);if(e.getX()>=x-a.dp(4)&&e.getX()<=x+w+a.dp(4)){go(i);break;}x+=w+a.dp(8);}performClick();}return true;}public boolean performClick(){super.performClick();return true;}}
}
